def _region_is_valid(row: dict[str, Any] | None) -> bool:
    if not row:
        return False
    status = str(row.get("状态", row.get("评估状态", ""))).upper()
    return status in {"VALID", "有效", "可评估", "检测完成", "候选检测结果"}


def _region_raw_value(row: dict[str, Any] | None, key: str) -> float | None:
