                module["核心指标"] = [row for row in module["核心指标"] if row["name"] == "痤疮样特征数量"]
                module["分区指标"] = []
        if module_id == "01":
            _, comparison = _pore_distribution(source)
            module["左右比较摘要"] = comparison
        formal["检测模块"].append(module)
    return copy.deepcopy(formal)


