def _one(folder: Path, suffix: str) -> Path:
    matches = [path for path in folder.glob(f"*{suffix}") if not path.name.startswith("~$")]
    if len(matches) != 1:
        raise RuntimeError(f"{folder} 期望1个{suffix}，实际{len(matches)}个")
    return matches[0]


def _load(path: Path) -> dict[str, Any]:
    return json.loads(path.read_text(encoding="utf-8"))


def _modules(document: dict[str, Any]) -> dict[str, dict[str, Any]]:
    return {str(row["模块编号"]): row for row in document["检测模块"]}


def _metric_map(module: dict[str, Any]) -> dict[str, Any]:
    return {str(row.get("name")): row.get("value") for row in module.get("核心指标", []) or []}


def _metric(module: dict[str, Any], name: str, default: Any = None) -> Any:
    for row in module.get("核心指标", []) or []:
        if row.get("name") == name:
            return row.get("value")
    return default


def _write_csv(path: Path, rows: list[dict[str, Any]]) -> None:
    if not rows:
        raise RuntimeError(f"拒绝写入空表: {path}")
    with path.open("w", encoding="utf-8-sig", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=list(rows[0]))
        writer.writeheader()
        writer.writerows(rows)


def _doc_data(path: Path) -> tuple[str, str, Document]:
    document = Document(path)
    text = "\n".join(
        [paragraph.text for paragraph in document.paragraphs]
        + [cell.text for table in document.tables for row in table.rows for cell in row.cells]
        + [
            paragraph.text
            for section in document.sections
            for block in (section.header, section.footer)
            for paragraph in block.paragraphs
        ]
    )
    with ZipFile(path) as archive:
        xml = "\n".join(
            archive.read(name).decode("utf-8", "ignore")
            for name in archive.namelist()
            if name.endswith(".xml")
        )
    return text, xml, document


def _paragraph_text(path: Path) -> list[str]:
    return [paragraph.text.strip() for paragraph in Document(path).paragraphs if paragraph.text.strip()]


def _chapter(paragraphs: list[str], module_id: str, next_id: str | None) -> str:
    start = next(
        (index for index, text in enumerate(paragraphs) if text.startswith(f"{module_id}  ") and index > 16),
        -1,
    )
    if start < 0:
        return ""
    end = len(paragraphs)
    if next_id:
        end = next(
            (index for index, text in enumerate(paragraphs[start + 1 :], start + 1) if text.startswith(f"{next_id}  ")),
            len(paragraphs),
        )
    return "\n".join(paragraphs[start:end])


def _summary_sentence(path: Path, module_id: str, next_id: str | None) -> str:
    lines = _chapter(_paragraph_text(path), module_id, next_id).splitlines()
    try:
        index = lines.index("结果摘要")
    except ValueError:
        return ""
    return lines[index + 1] if index + 1 < len(lines) else ""


def _json_equal_without_report_time(
    old: dict[str, Any], new: dict[str, Any], *, old_dir: Path, new_dir: Path
) -> bool:
    old_copy = json.loads(json.dumps(old, ensure_ascii=False))
    new_copy = json.loads(json.dumps(new, ensure_ascii=False))
    for data in (old_copy, new_copy):
        info = data.get("报告信息") or {}
        info.pop("报告编号", None)
        info.pop("生成时间", None)
    old_text = json.dumps(old_copy, ensure_ascii=False, sort_keys=True).replace(str(old_dir.resolve()), "<REPORT_DIR>")
    new_text = json.dumps(new_copy, ensure_ascii=False, sort_keys=True).replace(str(new_dir.resolve()), "<REPORT_DIR>")
    return old_text == new_text


def _field_audit_rows(sample: str, formal: dict[str, Any]) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for module in formal["检测模块"][:6]:
        module_id = str(module["模块编号"])
        locations: list[tuple[str, list[dict[str, Any]]]] = [("全面部", module.get("核心指标", []))]
        locations.extend(
            (f"医生分组/{group.get('title')}", group.get("metrics", []))
            for group in module.get("医生结果分组", []) or []
        )
        for region in module.get("分区指标", []) or []:
            locations.append((f"分区/{region.get('分区名称')}", list((region.get("指标") or {}).values())))
        for location, metrics in locations:
            for metric in metrics:
                if not isinstance(metric, dict) or "name" not in metric:
                    continue
                rows.append({
                    "样本": sample,
                    "项目": f"{module_id} {MODULE_NAMES[module_id]}",
                    "展示位置": location,
                    "医学名称": metric.get("medical_name", metric.get("name")),
                    "展示类型": metric.get("display_type"),
                    "单位": metric.get("unit", ""),
                    "数据来源": metric.get("source_path", ""),
                    "可用性": metric.get("availability", ""),
                    "解释": metric.get("explanation", ""),
                })
    return rows


