def _oil_distribution(module: dict[str, Any]) -> tuple[str, str, str, str]:
    rows = _region_source_map(module)
    leaf_names = [
        "额部", "鼻部", "画面左鼻旁", "画面右鼻旁", "画面左内侧面颊",
