            selected = [row for row in module["核心指标"] if row["name"] in selected_names]
            module["核心指标"] = selected or module["核心指标"][:4]
            dominant, comparison, regions = _pigmentation_distribution(source)
            module["分区指标"] = regions
            module["左右比较摘要"] = comparison
        elif module_id == "04":
